arguments.command:
gh pr list --repo cli/cli --search "created:2024-12-01..2024-12-31 is:merged" --json createdAt,mergedAt --jq -r '.[] | "\(.createdAt) \(.mergedAt)"' | awk '{
  split($1, created, "T")
  split($2, merged, "T")
  created_epoch = mktime(created[1] " " created[2])
  merged_epoch = mktime(merged[1] " " merged[2])
  diff_days = (merged_epoch - created_epoch) / 86400
  sum += diff_days
  count++
}
END {
  if (count > 0) {
    printf "%.1f\n", sum / count
  }
}'

